"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Evidence-reliability experiment, step 4: reliability read-out version 4 (plan summarised in docs/iterations.md,
2026-11-23; the author chose the explicit-doubt option and approved the flow: code and small checks, an independent AI review, fixes,
then run; review verdict "proceed after minor fixes", its items applied
below before anything heavy ran). Dev only, local only; no frozen file, setting or threshold changes; no backbone
forward.

Version 4 keeps the main system (the step 2d read-out, its thresholds, the step-1 inputs: no notification or service
line in the text) and adds two small models learned on train:
  confidence model (notifications unavailable): the decision is the main system's; a logistic regression per question
    estimates P(the main system is right) from [margin, side, clarity, margin x clarity, side x clarity]
    (margin = |logit p - logit th|, side = 1 when the decision is STOP / RESPOND, clarity = the version-2 encoder
    probe);
  notification model (notifications on): a logistic regression per question on [z, clarity, z x clarity]
    (z = logit p - logit th of the main system) plus structured notifications: per covered class (phone, doorbell,
    door) the time since its most recent notification in four bins ((0,2], (2,5], (5,10], >10 s; clips merged at gaps
    < 1 s as in version 3), and for phone and doorbell whether that notification began only after the current line
    began. It gives the decision (thresholds by the operating-point rule on natural dev with notifications on) and the
    confidence. The bins were set with the dev groups' event times in view (plan section 8).
Confident (as version 3): the system's probability for its chosen answer >= 0.9, i.e. P(right) of the confidence
model, or the notification model's probability of the chosen answer.
Training rows: every train question with a gold answer. Clean rows: the main system's own train forward (step 2c,
decoupled labels). Noisy rows: the version-1 noisy forward of the R-hear and S-move units drawn noisy (+10..40 dB),
only the windows whose labels were "decoupled" (review item 1: the "natural" half carries the detector's own, mostly
right labels, a condition no dev cell has). The main system's scores come from 5-fold cross-fitting by unit (same
design, standardisation and weight decay as the official read-out, which was refitted on all of train); clarity of
R-hear and S-move windows from a 5-fold cross-fitted probe (same alpha), other parts from the official probe (never
trained on them). Both small models use all rows (review item 8: the notification features exist for every row).
Dev: the step-1 forwards (none; c0.99 on R-hear, mv0.99 on S-move) at the five levels; conditions A-D as version 3
(service on / unavailable x labels none / fake); criteria 1-6 as version 3 word for word; 3 and 5 hold by construction.
Commands (repo root, .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_reliability_fix4.py ...):
  smoke     alignment checks, fold sizes, notification-feature counts and examples (train and dev), and a check that
            the main-system path reproduces version 3's step-1 recheck -> data/p1v4/runs/reliability/fix4/smoke.txt
  crossfit  the main read-out and the clarity probe cross-fitted; fold-model scale on natural dev
            -> fix4/crossfit_main.npz (saved right after the folds), fix4/crossfit.npz, fix4/crossfit_log.json
  fit       the two small models; the notification model's thresholds on natural dev -> fix4/models4.json
  eval      the criteria -> results/main_v04/reliability_step4_dev.json
"""
import collections
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_grounding as G  # noqa: E402
import p1v4_reliability_fix as FIX  # noqa: E402
import p1v4_reliability_fix2 as FIX2  # noqa: E402
import p1v4_reliability_fix3 as F3  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/reliability/fix4"
NOISY_NPZ = os.path.join(FIX.FIX, "feats_train_noisy.npz")
SEED4 = 20261125
K = 5
EDGES = (2.0, 5.0, 10.0)
CLASSES = ("phone", "doorbell", "door")
AFTER = ("phone", "doorbell")
NOTIF_NAMES = [f"{c} {b}" for c in CLASSES for b in ("0-2s", "2-5s", "5-10s", ">10s")] + \
              [f"{c} began after the line" for c in AFTER]
CONF_NAMES = ["margin", "side", "clarity", "margin x clarity", "side x clarity"]
CONF_P = 0.9
FEW = 30
C_LR = 1.0
EPS = 1e-6
LEVELS = F3.LEVELS
CONDS = F3.CONDS3


def _mk(d):
    os.makedirs(d, exist_ok=True)
    return d


def logit(p):
    p = np.clip(np.asarray(p, np.float64), EPS, 1 - EPS)
    return np.log(p / (1 - p))


def sigmoid(x):
    return 1 / (1 + np.exp(-np.asarray(x, np.float64)))


def main_th():
    import p1v4_reliability_dev as RD
    st = RD.rehearsal_settings()
    return {"S": float(st["main"]["th_s"]), "R": float(st["main"]["th_r"])}


def folds_of(units):
    """unit -> fold 0..K-1 (seeded permutation of the sorted unique units)."""
    uniq = sorted({str(u) for u in units})
    perm = np.random.default_rng(SEED4).permutation(len(uniq))
    return {u: int(perm[i] % K) for i, u in enumerate(uniq)}


def whole_chunked(sm, sx, idx, chunk=8192):
    """FIX2.whole on the windows idx of (sm, sx), in chunks (review item 2: no multi-GB transient copies)."""
    out = np.zeros((len(idx), 2 * sm.shape[2]), np.float32)
    for j in range(0, len(idx), chunk):
        sl = idx[j:j + chunk]
        out[j:j + len(sl)] = FIX2.whole(sm[sl], sx[sl])
    return out


# ------------------------------------------------------------------------------------------------ notifications

def segments(r, t, cls):
    xs = sorted((s["start"], s["end"]) for s in r["sources"]
                if s["kind"] == "clip" and s.get("cls") == cls and s["start"] < t)
    m = []
    for a, b in xs:
        if m and a - m[-1][1] < F3.MERGE_S:
            m[-1][1] = max(m[-1][1], b)
        else:
            m.append([a, b])
    return m


def line_start(r, w):
    if not w.get("line"):
        return None
    s = next((x for x in r["sources"] if x["kind"] == "speech" and x["id"] == w["line"]), None)
    return None if s is None else float(s["start"])


def notif_feats(r, w):
    """14 indicators (NOTIF_NAMES): per covered class the time since its most recent notification in four bins, and
    for phone and doorbell whether that notification began only after the current line began."""
    t, ls = float(w["t"]), line_start(r, w)
    bins, after = [], []
    for cls in CLASSES:
        seg = segments(r, t, cls)
        b = [0, 0, 0, 0]
        if seg:
            b[int(np.searchsorted(EDGES, t - seg[-1][0], side="left"))] = 1
        bins += b
        if cls in AFTER:
            after.append(int(bool(seg) and ls is not None and seg[-1][0] >= ls))
    return bins + after


# ------------------------------------------------------------------------------------------------ small models

def conf_X(p, c, th):
    p, c = np.asarray(p, np.float64), np.asarray(c, np.float64)
    m = np.abs(logit(p) - logit(th))
    s = (p >= th).astype(np.float64)
    return np.stack([m, s, c, m * c, s * c], 1)


def notif_X(p, c, th, F):
    c = np.asarray(c, np.float64)
    z = logit(p) - logit(th)
    return np.concatenate([np.stack([z, c, z * c], 1), np.asarray(F, np.float64).reshape(len(c), -1)], 1)


def _lr(X, y):
    from sklearn.linear_model import LogisticRegression
    m = LogisticRegression(C=C_LR, max_iter=10000).fit(X, y)
    return {"coef": [float(x) for x in m.coef_[0]], "intercept": float(m.intercept_[0])}


def _apply(model, X):
    return sigmoid(X @ np.array(model["coef"]) + model["intercept"])


def load_models():
    return json.load(open(os.path.join(OUT, "models4.json")))


# ------------------------------------------------------------------------------------------------ smoke

def smoke():
    lines = []

    def say(*a):
        s = " ".join(str(x) for x in a)
        print(s, flush=True)
        lines.append(s)

    z = np.load(FIX.F2C)
    ids, units_w = z["ids"].astype(str), z["units"].astype(str)
    q_win, q_task, q_gold = z["q_win"], z["q_task"].astype(str), z["q_gold"].astype(int)
    rows, wins = FIX.train_rows()
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    assert [w["id"] for w in wins] == list(ids), "train windows differ from the step 2c forward"
    assert np.array_equal(np.load(FIX.FSEC)["ids"].astype(str), ids), "per-second ears not aligned"
    zz = np.load(NOISY_NPZ)
    nids, ntask = zz["ids"].astype(str), zz["q_task"].astype(str)
    assert np.array_equal(zz["q_win"], np.arange(len(nids))), "noisy forward: not one question per window"
    a = FIX.load_assign()
    want = {w["id"] for w in wins if w["part"] in FIX.NOISY_PARTS and a["unit_db"].get(w["unit"], 0) > 0}
    assert want == set(nids), f"noisy windows differ from the version-1 draw ({len(want)} vs {len(set(nids))})"
    tasks = collections.defaultdict(dict)
    for j in range(len(q_task)):
        tasks[ids[q_win[j]]][q_task[j]] = int(q_gold[j])
    bad = [w for w, q in zip(nids, ntask) if q not in tasks[w]]
    assert not bad, f"{len(bad)} noisy questions without a 2c question, e.g. {bad[:3]}"
    extra = [w for w in nids if len(tasks[w]) != 1]
    say(f"alignment: {len(ids)} train windows, {len(q_task)} questions; {len(nids)} noisy windows, one question each, "
        f"tasks match the 2c forward; noisy windows with more than one 2c question: {len(extra)}")
    say("noisy windows by label regime and added dB:",
        dict(sorted(collections.Counter(zip(zz["regime"].astype(str), zz["db"].astype(int).tolist())).items())))
    fold = folds_of(units_w)
    say("fold sizes (units):", dict(sorted(collections.Counter(fold.values()).items())))
    on = F3.load_assign3()
    noisy = set(nids)
    mix = collections.Counter()
    for j in range(len(q_task)):
        if q_gold[j] < 0:
            continue
        w = wins[q_win[j]]
        db = a["unit_db"].get(w["unit"], 0) if w["id"] in noisy else 0
        mix[(q_task[j], w["part"], db, "on" if on[w["unit"]] else "off")] += 1
    say("training rows (question, part, added dB, service):")
    for k_, n in sorted(mix.items()):
        say("  ", k_, n)
    cnt = {q: np.zeros(len(NOTIF_NAMES), int) for q in ("S", "R")}
    pos = {q: np.zeros(len(NOTIF_NAMES), int) for q in ("S", "R")}
    nrow = collections.Counter()
    ex = []
    for j in range(len(q_task)):
        if q_gold[j] < 0:
            continue
        w = wins[q_win[j]]
        if not on[w["unit"]]:
            continue
        f = np.array(notif_feats(rows_by[w["key"]], w))
        q = q_task[j]
        cnt[q] += f
        pos[q] += f * int(q_gold[j])
        nrow[q] += 1
        if f.any() and len(ex) < 6 and (not ex or ex[-1][1] != w["part"]):
            ex.append((w["id"], w["part"], q, int(q_gold[j]), [NOTIF_NAMES[i] for i in np.where(f)[0]],
                       w["t"], line_start(rows_by[w["key"]], w)))
    for q in ("R", "S"):
        say(f"service-on training rows, question {q}: {nrow[q]}; per feature: n, share of the positive answer")
        for i, nm in enumerate(NOTIF_NAMES):
            if cnt[q][i]:
                say(f"   {nm:32s} n {cnt[q][i]:6d}  positive {pos[q][i] / cnt[q][i]:.3f}")
    say("examples (window, part, question, gold, active features, t, line start):")
    for e in ex:
        say("  ", e)
    rows_d, rows_by_d = G.load("dev")
    groups = G.load_groups("dev")
    gof = {g["unit"]: g for g in groups}
    keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
    gw = {w["id"]: w for w in D.windows_of(rows_d, "dev") if (w["unit"], w["version"], w["k"]) in keys}
    for lv in LEVELS:
        for cond in ("none", "c0.99", "mv0.99"):
            zid = np.load(f"{FIX.REL_DEV}/{lv}/l1_{cond}.npz")["ids"].astype(str)
            miss = [i for i in zid if i not in gw]
            assert not miss, f"{lv}/{cond}: {len(miss)} ids without a dev window"
    pat = collections.Counter()
    for wid, w in gw.items():
        g = gof[w["unit"]]
        f = notif_feats(rows_by_d[(w["unit"], w["version"])], w)
        q = "R" if g["part"] == "r_hear" else "S"
        pat[(g["part"], g["event"][0] if g["part"] == "r_hear" else "move", w["version"], w["gold"].get(q),
             tuple(NOTIF_NAMES[i] for i in np.where(f)[0]))] += 1
    say("dev grid windows (part, event, version, gold, active features): n")
    for k_, n in sorted(pat.items(), key=lambda kv: str(kv[0])):
        say("  ", k_, n)
    import p1v4_readout_2d as R2D
    import p1v4_reliability_dev as RD
    th = main_th()
    ref = json.load(open("results/main_v04/reliability_step3_dev.json"))["step1_recheck"]
    ro2d = R2D.load_2d()
    worst = 0.0
    for lv in LEVELS:
        for cond, part in (("none", "r_hear"), ("none", "s_move"), ("c0.99", "r_hear"), ("mv0.99", "s_move")):
            zd = dict(np.load(f"{FIX.REL_DEV}/{lv}/l1_{cond}.npz"))
            sec = R2D.Sec(None, zd["ids"], zd["sec_mean"], zd["sec_max"])
            qs = [x for x in F3.questions3(zd, RD.keyed(R2D.scores_2d(zd, sec, ro2d)), (th["S"], th["R"]))
                  if x[1] == part]
            s = F3.stats(qs)
            r_ = ref[part][cond]["2d"][lv]
            worst = max(worst, abs(s["accuracy"] - r_["accuracy"]), abs(s["confident_share"] - r_["confident_share"]))
    assert worst < 1e-12, f"main-system path differs from version 3 by {worst}"
    say(f"main-system path: version 3's step-1 recheck reproduced at every level and condition (max diff {worst:.1e})")
    _mk(OUT)
    open(os.path.join(OUT, "smoke.txt"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
    print(f"-> {OUT}/smoke.txt", flush=True)


# ------------------------------------------------------------------------------------------------ crossfit

def crossfit():
    import torch
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    D.gpu_guard()
    t0 = time.time()
    z = np.load(FIX.F2C)
    ids, units_w = z["ids"].astype(str), z["units"].astype(str)
    q_win, q_task, q_gold = z["q_win"], z["q_task"].astype(str), z["q_gold"].astype(int)
    states = z["states"]
    e = np.load(FIX.FSEC)
    assert np.array_equal(e["ids"].astype(str), ids)
    sm_all, sx_all = e["sec_mean"], e["sec_max"]
    zz = np.load(NOISY_NPZ)
    nids = zz["ids"].astype(str)
    assert np.array_equal(zz["q_win"], np.arange(len(nids)))
    nst, nsm, nsx = zz["states"], zz["sec_mean"], zz["sec_max"]          # review item 2: each member read once
    ntask, nreg, ndb = zz["q_task"].astype(str), zz["regime"].astype(str), zz["db"].astype(int)
    npos = {w: i for i, w in enumerate(nids)}
    fold = folds_of(units_w)
    ro = R2D.load_2d()
    th = main_th()
    zn = np.load(f"{RO.OUT}/feats_dev_natural.npz")                     # review item 6: fold-model scale
    zn_states, zn_ids, zn_qwin, zn_task = zn["states"], zn["ids"], zn["q_win"], zn["q_task"].astype(str)
    secn = R2D.Sec()
    log = {"folds": K, "seed": SEED4, "main": {}, "probe": {}, "fold_scale_on_natural_dev": {}}
    rec = {k: [] for k in ("q", "win", "unit", "gold", "noisy", "regime", "db", "p")}
    for q in ("S", "R"):
        m = np.where((q_task == q) & (q_gold >= 0))[0]
        wq = q_win[m]
        fq = np.array([fold[units_w[i]] for i in wq])
        X = R2D.design(states[m], sm_all[wq], sx_all[wq])
        X -= ro[q]["mu"]
        X /= ro[q]["sd"]
        Xh = X.astype(np.float16)
        del X
        y = q_gold[m]
        has = np.array([ids[i] in npos for i in wq])
        ni = np.array([npos[ids[i]] for i in wq[has]], int)
        assert (ntask[ni] == q).all(), "noisy question task differs"
        Xn = R2D.design(nst[ni], nsm[ni], nsx[ni])
        Xn -= ro[q]["mu"]
        Xn /= ro[q]["sd"]
        Xnh = Xn.astype(np.float16)
        del Xn
        mn = np.where(zn_task == q)[0]
        rn = secn.rows(zn_ids[zn_qwin[mn]])
        Xd = R2D.design(zn_states[mn], secn.sm[rn], secn.sx[rn])
        Xd -= ro[q]["mu"]
        Xd /= ro[q]["sd"]
        lg_off = Xd @ ro[q]["w"] + float(ro[q]["b"])
        Xdh = Xd.astype(np.float16)
        del Xd
        fn = fq[has]
        p_clean, p_noisy = np.zeros(len(m)), np.zeros(int(has.sum()))
        wd = float(ro[q]["wd"])
        scale = []
        for f in range(K):
            lin = RO.train_logreg(Xh[fq != f], y[fq != f], wd)
            p_clean[fq == f] = RO.predict(lin, Xh[fq == f])
            if (fn == f).any():
                p_noisy[fn == f] = RO.predict(lin, Xnh[fn == f])
            lg_f = logit(RO.predict(lin, Xdh))
            scale.append({"fold": f, "mean_abs_logit_ratio": float(np.mean(np.abs(lg_f)) / np.mean(np.abs(lg_off))),
                          "decision_agreement": float(np.mean((lg_f >= logit(th[q])) == (lg_off >= logit(th[q]))))})
            del lin
            torch.cuda.empty_cache()
            print(f"crossfit {q} fold {f}: {time.time() - t0:.0f} s; natural-dev scale {scale[-1]}", flush=True)
        log["fold_scale_on_natural_dev"][q] = scale
        p_row = p_clean.copy()
        p_row[has] = p_noisy
        reg = np.array(["decoupled"] * len(m), dtype=object)
        reg[has] = nreg[ni]
        db = np.zeros(len(m), int)
        db[has] = ndb[ni]
        yn = y[has]
        by = {}
        for r_ in ("decoupled", "natural"):
            for d in (10, 20, 30, 40):
                s_ = (nreg[ni] == r_) & (ndb[ni] == d)
                if s_.any():
                    by[f"{r_} +{d}"] = {"n": int(s_.sum()),
                                         "oof_accuracy": float(np.mean((p_noisy[s_] >= th[q]) == (yn[s_] == 1)))}
        log["main"][q] = {"weight_decay": wd, "rows": int(len(m)), "noisy_rows": int(has.sum()),
                          "oof_accuracy_clean_rows": float(np.mean((p_clean[~has] >= th[q]) == (y[~has] == 1))),
                          "oof_accuracy_noisy_rows_by_regime_and_db": by}
        rec["q"] += [q] * len(m)
        rec["win"] += [ids[i] for i in wq]
        rec["unit"] += [units_w[i] for i in wq]
        rec["gold"] += list(y)
        rec["noisy"] += list(has)
        rec["regime"] += list(reg)
        rec["db"] += list(db)
        rec["p"] += list(p_row)
        del Xh, Xnh, Xdh
    np.savez(os.path.join(_mk(OUT), "crossfit_main.npz"), **{k: np.array(v) for k, v in rec.items()})
    print(f"fold scores saved ({time.time() - t0:.0f} s)", flush=True)
    # clarity: cross-fitted probe on the R-hear and S-move windows (their version in the mix), official elsewhere
    a = FIX.load_assign()
    rows, wins = FIX.train_rows()
    snr0 = {r["unit"]: float(r["spec"]["snr_db"]) for r in rows if r["part"] in FIX.NOISY_PARTS}
    pr = FIX2.load_probe()
    alpha = float(np.load(os.path.join(FIX.FIX, "clarity_probe.npz"))["alpha"])
    pos = {w: i for i, w in enumerate(ids)}
    keep = [w for w in wins if w["unit"] in snr0]
    isn = np.array([w["id"] in npos for w in keep])
    Wk = np.zeros((len(keep), 2 * sm_all.shape[2]), np.float32)
    Wk[isn] = whole_chunked(nsm, nsx, np.array([npos[w["id"]] for w in keep if w["id"] in npos], int))
    Wk[~isn] = whole_chunked(sm_all, sx_all, np.array([pos[w["id"]] for w in keep if w["id"] not in npos], int))
    yk = np.array([snr0[w["unit"]] - (a["unit_db"][w["unit"]] if w["id"] in npos else 0) for w in keep], np.float64)
    fk = np.array([fold[w["unit"]] for w in keep])
    snr_oof = np.zeros(len(keep))
    for f in range(K):
        tr = fk != f
        mu, sd = Wk[tr].mean(0), Wk[tr].std(0) + 1e-6
        Xt = (Wk[tr] - mu) / sd
        ym = yk[tr].mean()
        wv = np.linalg.solve(Xt.T @ Xt + alpha * np.eye(Xt.shape[1]), Xt.T @ (yk[tr] - ym))
        snr_oof[~tr] = ((Wk[~tr] - mu) / sd) @ wv + ym
    c_keep = np.clip((snr_oof - FIX2.SNR_LO) / (FIX2.SNR_HI - FIX2.SNR_LO), 0.0, 1.0)
    clar = {w["id"]: float(c) for w, c in zip(keep, c_keep)}
    others = np.array([i for i, w in enumerate(ids) if w not in clar], int)
    c_off, _ = FIX2.clarity_of(whole_chunked(sm_all, sx_all, others), pr)
    for i, c in zip(others, c_off):
        clar[ids[i]] = float(c)
    db_k = np.array([a["unit_db"][w["unit"]] if w["id"] in npos else 0 for w in keep])
    log["probe"] = {"alpha": alpha, "windows": len(keep), "oof_mae_db": float(np.mean(np.abs(snr_oof - yk))),
                    "by_added_db": {int(d): {"true_snr_mean": float(yk[db_k == d].mean()),
                                             "oof_pred_snr_mean": float(snr_oof[db_k == d].mean()),
                                             "oof_mae_db": float(np.mean(np.abs(snr_oof - yk)[db_k == d])),
                                             "clarity_mean": float(c_keep[db_k == d].mean())}
                                    for d in sorted(set(db_k.tolist()))},
                    "other_parts_clarity_mean": float(np.mean(c_off))}
    on = F3.load_assign3()
    np.savez(os.path.join(OUT, "crossfit.npz"), row_q=np.array(rec["q"]), row_win=np.array(rec["win"]),
             row_unit=np.array(rec["unit"]), row_gold=np.array(rec["gold"], int), row_noisy=np.array(rec["noisy"]),
             row_regime=np.array(rec["regime"]).astype(str), row_db=np.array(rec["db"], int),
             row_p=np.array(rec["p"]), row_c=np.array([clar[w] for w in rec["win"]]),
             row_on=np.array([bool(on[u]) for u in rec["unit"]]))
    log["seconds"] = time.time() - t0
    json.dump(log, open(os.path.join(OUT, "crossfit_log.json"), "w"), indent=1)
    print(json.dumps(log, indent=1), flush=True)


# ------------------------------------------------------------------------------------------------ fit

def _calibration(p_right, right, c):
    out = {}
    for lo, hi in ((0.0, 0.2), (0.2, 0.4), (0.4, 0.6), (0.6, 0.8), (0.8, 1.01)):
        m = (c >= lo) & (c < hi)
        if not m.any():
            continue
        cf = p_right[m] >= CONF_P
        out[f"{lo:.1f}-{min(hi, 1.0):.1f}"] = {
            "n": int(m.sum()), "mean_p_right": float(p_right[m].mean()), "accuracy": float(right[m].mean()),
            "confident_share": float(cf.mean()),
            "confident_error_rate": float(1 - right[m][cf].mean()) if cf.any() else None}
    return out


def natural_scores(models, th, on):
    """{(unit, version, k): {q: p}} on natural dev: the main system (on=False) or the notification model (on=True)."""
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_reliability_dev as RD
    rows_d, rows_by_d = G.load("dev")
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    sec = R2D.Sec()
    main = RD.keyed(R2D.scores_2d(zn, sec, R2D.load_2d()))
    if not on:
        return main
    pr = FIX2.load_probe()
    cd, _ = FIX2.clarity_of(FIX2.whole(sec.sm, sec.sx), pr)
    wins = {w["id"]: w for w in D.windows_of(rows_d, "dev")}
    out = {}
    for (u, v, k), d in main.items():
        wid = f"{u}|{v}|{k}"
        f = notif_feats(rows_by_d[(u, v)], wins[wid])
        c = float(cd[sec.pos[wid]])
        out[(u, v, k)] = {q: float(_apply(models["notification"][q], notif_X([p], [c], th[q], [f]))[0])
                          for q, p in d.items()}
    return out


def fit():
    import p1v4_score as S
    cf = np.load(os.path.join(OUT, "crossfit.npz"))
    use = ~(cf["row_noisy"] & (cf["row_regime"] == "natural"))       # review item 1
    rows, wins = FIX.train_rows()
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    wmap = {w["id"]: w for w in wins}
    cache = {}

    def feat(wid):
        if wid not in cache:
            w = wmap[wid]
            cache[wid] = notif_feats(rows_by[w["key"]], w)
        return cache[wid]

    th = main_th()
    models = {"confidence": {}, "notification": {}, "features": {"confidence": CONF_NAMES,
                                                                 "notification": ["z", "clarity", "z x clarity"] +
                                                                 NOTIF_NAMES},
              "main_thresholds": th, "train (in-sample)": {}}
    keep = {}
    for q in ("S", "R"):
        sel = (cf["row_q"] == q) & use
        p, c, g = cf["row_p"][sel], cf["row_c"][sel], cf["row_gold"][sel]
        wq = cf["row_win"][sel]
        right = ((p >= th[q]) == (g == 1)).astype(int)
        Xc = conf_X(p, c, th[q])
        models["confidence"][q] = _lr(Xc, right)
        pr_ = _apply(models["confidence"][q], Xc)
        F = np.array([feat(w) for w in wq])
        Xn = notif_X(p, c, th[q], F)
        models["notification"][q] = _lr(Xn, g)
        pn = _apply(models["notification"][q], Xn)
        keep[q] = (wq, g, pn, F, cf["row_db"][sel])
        allq = cf["row_q"] == q
        models["train (in-sample)"][q] = {
            "rows": int(sel.sum()), "noisy_rows_kept": int((cf["row_noisy"] & allq & use).sum()),
            "noisy_rows_dropped_natural_labels": int((allq & ~use).sum()),
            "confidence_calibration_by_clarity": _calibration(pr_, right, c),
            "notification_log_loss": float(-np.mean(g * np.log(np.clip(pn, EPS, 1)) +
                                                    (1 - g) * np.log(np.clip(1 - pn, EPS, 1))))}
        print(f"fit {q}: rows {int(sel.sum())}; confidence {models['confidence'][q]}\n"
              f"       notification {models['notification'][q]}", flush=True)
    rows_d, _ = G.load("dev")
    op = S.operating_point(rows_d, natural_scores(models, th, True))
    th4 = {"S": float(op["th_s"]), "R": float(op["th_r"])}
    models["notification_thresholds"] = th4
    models["notification_operating_point"] = {k: op[k] for k in ("th_s", "th_r", "floors_met", "primary",
                                                                  "lowest_floor")}
    # review item 9: the notification model's accuracy on the R-hear and S-move train rows (in-sample), by added dB
    # and by whether a notification is present
    for q, part in (("R", "r_hear"), ("S", "s_move")):
        wq, g, pn, F, db = keep[q]
        prt = np.array([wmap[w]["part"] == part for w in wq])
        has = F.any(1)
        tab = {}
        for d in (0, 10, 20, 30, 40):
            for h in (True, False):
                s_ = prt & (db == d) & (has == h)
                if s_.any():
                    tab[f"+{d} dB, notification {'present' if h else 'absent'}"] = {
                        "n": int(s_.sum()), "accuracy": float(np.mean((pn[s_] >= th4[q]) == (g[s_] == 1))),
                        "confident_share": float(np.mean(np.where(pn[s_] >= th4[q], pn[s_] >= CONF_P,
                                                                  pn[s_] <= 1 - CONF_P)))}
        models["train (in-sample)"][q][f"notification_model_on_{part}"] = tab
    json.dump(models, open(os.path.join(OUT, "models4.json"), "w"), indent=1, default=float)
    print("notification thresholds on natural dev (notifications on):", models["notification_operating_point"],
          flush=True)
    for q in ("R", "S"):
        print(f"train (in-sample) {q}:", json.dumps(models["train (in-sample)"][q], indent=1), flush=True)


# ------------------------------------------------------------------------------------------------ eval

def items_v4(z, sc_main, th, models, th4, on, rows_by, wins, pr):
    """[(unit, part, task, p, confident, confident, right, window id)] of version 4 (positions 0-6 as version 3)."""
    c_w, _ = FIX2.clarity_of(FIX2.whole(z["sec_mean"], z["sec_max"]), pr)
    out = []
    for j in range(len(z["q_task"])):
        g = int(z["q_gold"][j])
        if g < 0:
            continue
        i = int(z["q_win"][j])
        wid = str(z["ids"][i])
        u, v, k = wid.split("|")
        q = str(z["q_task"][j])
        p = sc_main[(u, v, int(k))][q]
        c = float(c_w[i])
        if on:
            f = notif_feats(rows_by[(u, v)], wins[wid])
            pp = float(_apply(models["notification"][q], notif_X([p], [c], th[q], [f]))[0])
            pos = pp >= th4[q]
            conf = (pp >= CONF_P) if pos else (pp <= 1 - CONF_P)
        else:
            pp = p
            pos = p >= th[q]
            conf = float(_apply(models["confidence"][q], conf_X([p], [c], th[q]))[0]) >= CONF_P
        out.append((u, str(z["parts"][i]), q, pp, bool(conf), bool(conf), pos == bool(g), wid))
    return out


def boot_pair(sel_a, sel_b, fn, seed=0):
    """Percentile 95% interval of fn(a) - fn(b), resampling groups (units) with the same draw for both."""
    ba, bb = collections.defaultdict(list), collections.defaultdict(list)
    for x in sel_a:
        ba[x[0]].append(x)
    for x in sel_b:
        bb[x[0]].append(x)
    units = sorted(set(ba) & set(bb))
    rng = np.random.default_rng(seed)
    vals = []
    for _ in range(F3.N_BOOT):
        pick = rng.integers(0, len(units), len(units))
        vals.append(fn([x for i in pick for x in ba[units[i]]]) - fn([x for i in pick for x in bb[units[i]]]))
    return [float(np.quantile(vals, 0.025)), float(np.quantile(vals, 0.975))]


def eval_():
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_reliability_dev as RD
    import p1v4_score as S
    models = load_models()
    th = main_th()
    th4 = models["notification_thresholds"]
    st = RD.rehearsal_settings()
    ths = {"2d": (th["S"], th["R"]), "old head": (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"])}
    ro2d, pr = R2D.load_2d(), FIX2.load_probe()
    rows_d, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
    wins = {w["id"]: w for w in D.windows_of(rows_d, "dev") if (w["unit"], w["version"], w["k"]) in keys}
    cov = {g["unit"]: F3.covered(g, rows_by) for g in groups}
    counts = collections.Counter((g["part"], cov[g["unit"]]) for g in groups)
    res = {"split": "dev", "note": "exploratory (evidence-reliability step 4, version 4, after the Fable review)",
           "thresholds": {"main": th, "notification model": th4, "old head": ths["old head"]},
           "notification_operating_point": models["notification_operating_point"],
           "confident": f"probability of the chosen answer >= {CONF_P} (version 4 without notifications: the "
                        f"confidence model's P(right))",
           "coverage": {f"{p} {'covered' if c else 'not covered'}": n for (p, c), n in sorted(counts.items())},
           "cells": {}, "natural": {}, "criteria": {}, "descriptive": {}}
    Q = {}

    def subsets(qs, part):
        out = {"all": [x for x in qs if x[1] == part]}
        out["covered"] = [x for x in out["all"] if cov[x[0]]]
        out["not covered"] = [x for x in out["all"] if not cov[x[0]]]
        return {k_: v for k_, v in out.items() if v}

    clar = {}
    for lv in LEVELS:
        zs = {c: dict(np.load(f"{FIX.REL_DEV}/{lv}/l1_{c}.npz")) for c in ("none", "c0.99", "mv0.99")}
        clar[lv] = float(FIX2.clarity_of(FIX2.whole(zs["none"]["sec_mean"], zs["none"]["sec_max"]), pr)[0].mean())
        for cond, (on, lab) in CONDS.items():
            parts_z = [zs["none"]] if lab == "none" else [zs["c0.99"], zs["mv0.99"]]
            qs = {n: [] for n in ("2d", "old head", "rel v4")}
            for zd in parts_z:
                sec = R2D.Sec(None, zd["ids"], zd["sec_mean"], zd["sec_max"])
                sc_main = RD.keyed(R2D.scores_2d(zd, sec, ro2d))
                qs["2d"] += F3.questions3(zd, sc_main, ths["2d"])
                qs["old head"] += F3.questions3(zd, RD.keyed(RO.scores_of(zd, None, None)), ths["old head"])
                qs["rel v4"] += items_v4(zd, sc_main, th, models, th4, on, rows_by, wins, pr)
            for n, qq in qs.items():
                for part in ("r_hear", "s_move"):
                    for sub, sel in subsets(qq, part).items():
                        Q[(part, cond, n, lv, sub)] = sel
                        s_ = F3.stats(sel)
                        if n == "rel v4":                            # review item 7: no second measure here
                            s_.pop("confident_share_threshold_distance")
                            s_.pop("confident_error_rate_threshold_distance")
                        s_["group_all_right"] = float(np.mean(list(F3.all_right(sel).values())))
                        res["cells"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {}).setdefault(
                            sub, {})[lv] = s_
    res["descriptive"]["dev_clarity_mean_by_level"] = clar
    gmap = S.load_groups("dev")
    for name, sc, t_ in (("2d, standard", natural_scores(models, th, False), (th["S"], th["R"])),
                         ("rel v4, notifications unavailable", natural_scores(models, th, False), (th["S"], th["R"])),
                         ("rel v4, notifications on", natural_scores(models, th, True), (th4["S"], th4["R"]))):
        m_ = S.metrics(S.unit_table(rows_d, S.decide(sc, *t_), gmap))
        res["natural"][name] = {"primary": m_["primary"], "parts": m_["parts"], "floors": m_["floors"]}

    def acc_fn(sel):
        return float(np.mean([x[6] for x in sel]))

    def cer_fn(sel):
        cp = [x for x in sel if x[4]]
        return float(np.mean([not x[6] for x in cp])) if cp else None

    def share_fn(sel):
        return float(np.mean([x[4] for x in sel]))

    def judge(point, ci, bar, higher=True):
        ok = point is None or (point >= bar if higher else point <= bar)
        unclear = ci is not None and ci[0] <= bar <= ci[1]
        return {"pass": bool(ok), "unclear": bool(unclear)}

    def event_member(x):
        g = wins[x[7]]["gold"][x[2]]
        return g == ("not" if x[2] == "R" else "stop")

    crit = {}
    c1 = {}
    for p in ("r_hear", "s_move"):
        for lv in ("dnoise20", "dnoise30", "dnoise40"):
            sel = Q[(p, "A_on_none", "rel v4", lv, "covered")]
            v, ci = acc_fn(sel), F3.boot(sel, acc_fn)
            ev = [x for x in sel if event_member(x)]
            ne = [x for x in sel if not event_member(x)]
            c1[f"{p} {lv}"] = {"accuracy": v, "ci95": ci, "event members": acc_fn(ev), "n event": len(ev),
                               "no-event members": acc_fn(ne), "n no-event": len(ne), **judge(v, ci, 0.95)}
    crit["1 notifications on, ears bad, covered events: accuracy >= 0.95"] = c1
    c2 = {}
    for p in ("r_hear", "s_move"):
        for lv in LEVELS:
            sel = Q[(p, "B_on_fake", "rel v4", lv, "covered")]
            v, ci = acc_fn(sel), F3.boot(sel, acc_fn)
            ev = [x for x in sel if event_member(x)]
            ne = [x for x in sel if not event_member(x)]
            c2[f"{p} {lv}"] = {"accuracy": v, "ci95": ci, "event members": acc_fn(ev), "n event": len(ev),
                               "no-event members": acc_fn(ne), "n no-event": len(ne), **judge(v, ci, 0.95)}
    crit["2 notifications on vs fake detector labels, covered events: accuracy >= 0.95"] = c2
    c3 = {}
    for p in ("r_hear", "s_move"):
        a_new = F3.all_right(Q[(p, "C_off_fake", "rel v4", "dclean", "all")])
        a_ref = F3.all_right(Q[(p, "C_off_fake", "2d", "dclean", "all")])
        gap_items = [(u, None, None, None, None, None, a_new[u] - a_ref[u]) for u in sorted(a_new)]
        gap = float(np.mean([x[6] for x in gap_items]))
        ci = F3.boot(gap_items, lambda sel: float(np.mean([x[6] for x in sel])))
        c3[p] = {"rel v4": float(np.mean(list(a_new.values()))), "main system": float(np.mean(list(a_ref.values()))),
                 "gap": gap, "ci95": ci, "by construction": True, **judge(gap, ci, -0.05)}
    crit["3 notifications unavailable, fake labels, clean: group all-right within 5 points of the main system"] = c3
    c4 = {}
    for p in ("r_hear", "s_move"):
        for c in ("C_off_fake", "D_off_none"):
            for lv in ("dnoise30", "dnoise40"):
                sel = Q[(p, c, "rel v4", lv, "all")]
                v, ci = cer_fn(sel), F3.boot(sel, cer_fn)
                nc = int(sum(x[4] for x in sel))
                c4[f"{p} {c} {lv}"] = {"confident_error_rate": v, "n_confident": nc, "n": len(sel), "ci95": ci,
                                       **({"note": "no confident decisions (fewer than 30)"} if nc < FEW else {}),
                                       **judge(v, ci, 0.10, higher=False)}
    crit["4 notifications unavailable, ears bad: confident errors <= 10%"] = c4
    c4b = {}
    for p in ("r_hear", "s_move"):
        sel = Q[(p, "D_off_none", "rel v4", "dclean", "all")]
        ref = Q[(p, "D_off_none", "2d", "dclean", "all")]
        v, r_ = share_fn(sel), share_fn(ref)
        ci = boot_pair(sel, ref, share_fn)                            # review item 11
        c4b[p] = {"rel v4": v, "main system": r_, "difference": v - r_, "ci95_difference": ci,
                  **judge(v - r_, ci, -0.10)}
    crit["4' notifications unavailable, no labels, clean: confident share within 10 points of the main system"] = c4b
    nn = res["natural"]["rel v4, notifications unavailable"]["primary"]
    nm = res["natural"]["2d, standard"]["primary"]
    crit["5 natural dev: five-part mean within 3 points of the main system"] = {
        "all": {"rel v4": nn, "main system": nm, "gap": nn - nm, "by construction": True,
                **judge(nn - nm, None, -0.03)}}
    c6 = {}
    for c in ("A_on_none", "B_on_fake"):
        for lv in ("dnoise30", "dnoise40"):
            sel = Q[("r_hear", c, "rel v4", lv, "not covered")]
            v, ci = cer_fn(sel), F3.boot(sel, cer_fn)
            nc = int(sum(x[4] for x in sel))
            c6[f"r_hear knock {c} {lv}"] = {"confident_error_rate": v, "n_confident": nc, "n": len(sel), "ci95": ci,
                                            **({"note": "no confident decisions (fewer than 30)"} if nc < FEW else {}),
                                            **judge(v, ci, 0.10, higher=False)}
    crit["6 notifications on, knock (not covered), ears bad: confident errors <= 10%"] = c6
    for k_, cells in crit.items():
        res["criteria"][k_] = {"cells": cells, "pass": all(v["pass"] for v in cells.values()),
                               "unclear": any(v["unclear"] for v in cells.values())}
    # construction checks, not evidence (review item 10): without notifications the decisions are the main system's
    assert abs(nn - nm) < 1e-12 and all(abs(v["gap"]) < 1e-12 for v in c3.values())
    # report only (review item 4): confident share and errors by level without notifications, version 4 and main
    rep4 = {}
    for p in ("r_hear", "s_move"):
        for c in ("C_off_fake", "D_off_none"):
            for n in ("rel v4", "2d"):
                rep4[f"{p} {c} {n}"] = {lv[1:]: {"confident_share": share_fn(Q[(p, c, n, lv, "all")]),
                                                 "n_confident": int(sum(x[4] for x in Q[(p, c, n, lv, "all")])),
                                                 "confident_error_rate": cer_fn(Q[(p, c, n, lv, "all")])}
                                        for lv in LEVELS}
    res["descriptive"]["confidence_by_level_without_notifications"] = rep4
    # report only (review item 3): R-hear questions without a notification, A and B at +30/+40: knock groups and the
    # covered groups' no-event versions, mean P(RESPOND) and confident share
    rep6 = {}
    for c in ("A_on_none", "B_on_fake"):
        for lv in ("dnoise30", "dnoise40"):
            sel = Q[("r_hear", c, "rel v4", lv, "all")]
            for name, f_ in (("knock groups, all versions", lambda x: not cov[x[0]]),
                             ("covered groups, no-event versions", lambda x: cov[x[0]] and not event_member(x))):
                xs = [x for x in sel if f_(x)]
                rep6[f"{c} {lv} {name}"] = {"n": len(xs), "mean_p_respond": float(np.mean([x[3] for x in xs])),
                                            "confident_share": share_fn(xs), "accuracy": acc_fn(xs)}
    res["descriptive"]["r_hear_without_notification"] = rep6
    shift = {}
    for p in ("r_hear", "s_move"):
        for lv in LEVELS:
            cell = {}
            for cond in ("A_on_none", "D_off_none"):
                sel = Q[(p, cond, "rel v4", lv, "covered")]
                for name, xs in (("event", [x for x in sel if event_member(x)]),
                                 ("no event", [x for x in sel if not event_member(x)])):
                    cell[f"{cond} {name}"] = {"n": len(xs), "mean_p_positive": float(np.mean([x[3] for x in xs])),
                                              "accuracy": acc_fn(xs)}
            shift.setdefault(p, {})[lv] = cell
    res["descriptive"]["covered_groups_by_member"] = shift
    json.dump(res, open("results/main_v04/reliability_step4_dev.json", "w"), indent=1, default=float)
    print("thresholds:", json.dumps(res["thresholds"]), "coverage:", json.dumps(res["coverage"]))
    print("notification operating point:", json.dumps(res["notification_operating_point"], default=float))
    print("dev clarity by level:", json.dumps({k_: round(v, 3) for k_, v in clar.items()}))
    print("natural:", json.dumps({k_: round(v["primary"], 3) for k_, v in res["natural"].items()}))
    for k_, v in res["criteria"].items():
        print(f"CRITERION {k_}: {'PASS' if v['pass'] else 'FAIL'}{' (unclear)' if v['unclear'] else ''}")
        for ck, cv in v["cells"].items():
            print("   ", ck, json.dumps({a: (round(b, 3) if isinstance(b, float) else
                                            [round(x, 3) for x in b] if isinstance(b, list) else b)
                                         for a, b in cv.items()}))
    print("== report only: confident share | n confident | confident errors without notifications, by level")
    for k_, v in rep4.items():
        print(f"  {k_:28s} " + " | ".join(
            f"{lv}: {x['confident_share']:.3f} {x['n_confident']:3d} " +
            ("none" if x["n_confident"] < FEW else f"{x['confident_error_rate']:.3f}") for lv, x in v.items()))
    print("== report only: R-hear without a notification (A, B; +30/+40): n | mean P(respond) | confident share | acc")
    for k_, v in rep6.items():
        print(f"  {k_:52s} {v['n']:4d} {v['mean_p_respond']:.3f} {v['confident_share']:.3f} {v['accuracy']:.3f}")
    print("== covered groups by member: mean P(positive) | accuracy (A = notification model, D = main system)")
    for p, levels in shift.items():
        for lv, cell in levels.items():
            print(f"  {p} {lv[1:]}: " + " | ".join(f"{k_} {x['mean_p_positive']:.2f} {x['accuracy']:.2f} n{x['n']}"
                                                   for k_, x in cell.items()))
    for part, cs in res["cells"].items():
        for cond, ns in cs.items():
            print(f"== {part} / {cond} (all groups): accuracy | group all-right | confident share | confident errors")
            for n, subs in ns.items():
                cells = []
                for lv, x in subs["all"].items():
                    ce = "n/a" if x["confident_error_rate"] is None else f"{x['confident_error_rate']:.3f}"
                    cells.append(f"{lv[1:]}: {x['accuracy']:.3f} {x['group_all_right']:.3f} "
                                 f"{x['confident_share']:.3f} {ce}")
                print(f"  {n:9s} " + " | ".join(cells))
    print("-> results/main_v04/reliability_step4_dev.json")


